import fs from 'node:fs/promises';
import {RemoteD1Database} from '../runner/report2-d1-adapter.mjs';
import {loadDailyUsageAggregate,evaluateDailyReservationBudget,reserveRunBudget,finalizeRunUsage} from '../runner/d1-preaction-budget-guard.mjs';
import {readMarketHistoryForContract} from '../current-generation/files/src/market-history-reader.mjs';
const saved=JSON.parse(await fs.readFile('checkpoints/native-source-batch-tests-37799119119/natural-sent-task-read.json'));
const db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),now=Date.now(),reservation={rows_read:4000,rows_written:20},id='RETAINED_TRIGGER_WINDOW:'+process.env.GITHUB_RUN_ID;
const out={schema:'ORIGINAL_COLLECTOR_PRICES_IN_EXACT_SENT_TTL_V1',cloud_run:process.env.GITHUB_RUN_ID,head:process.env.GITHUB_SHA,read_ts:now,sourceHTTP:0,MAIN:0,Telegram:0,task_writes:0,source_clocks_refreshed:false,actual_ENTRY:false,cases:[],limitation:'A retained collector price satisfying the price predicate is not settlement, a complete entry decision, or proof that a full analysis ran. Source clocks and original task lifetime stay unchanged.'};
const compare=(p,op,v)=>op==='>='?p>=v:op==='<='?p<=v:op==='>'?p>v:op==='<'?p<v:false;
out.admission=evaluateDailyReservationBudget({daily:await loadDailyUsageAggregate(db,now),nextReservation:reservation,maxDailyReads:3500000,maxDailyWrites:70000});
if(out.admission.allowed){await reserveRunBudget(db,{reservationId:id,now,reservation});try{for(const c of saved.cases){
 if(!c.exact_SENT)throw Error('EXACT_ORIGINAL_SENT_REQUIRED');
 const t=c.original_trigger,history=await readMarketHistoryForContract({db,contract:c.contract,now_ts:t.expires_ts,hours:1}),cancel=t.cancel_condition.match(/^price(>=|<=|>|<)([0-9.]+)$/),points=history.series.filter(p=>p.ts>=t.next_recheck_ts&&p.ts<=t.expires_ts&&p.source_status==='CLOSED');
 out.cases.push({contract:c.contract,publication_id:c.publication_id,run_id:c.run_id,snapshot_id:c.snapshot_id,source_cloud_run:c.source_cloud_run,source_head:c.source_head,telegram_message_id:c.receipt.telegram_message_id,original_trigger:t,task_read_state:c.task?.state,task_attempt_count:c.task?.attempt_count,history_status:history.status,source:history.source,coverage:history.coverage,provenance:history.provenance,d1:history.d1,points:points.map(p=>({...p,trigger_price_reached:compare(p.price,t.operator,t.value),cancel_price_reached:compare(p.price,cancel[1],Number(cancel[2]))})),retained_price_trigger_reached:points.some(p=>compare(p.price,t.operator,t.value)&&!compare(p.price,cancel[1],Number(cancel[2])))});
 const u=db.usageSnapshot();if(u.unknown_ops||u.rows_read>3700||u.rows_written>18||u.requests>22)throw Error('BOUNDED_READ_EXCEEDED');
}out.status='EXACT_RETAINED_TTL_PRICE_WINDOWS_READ';}catch(e){out.status='READ_FAILED';out.error=String(e.message).slice(0,200);}finally{out.finalized_usage=await finalizeRunUsage(db,{reservationId:id,sourceRunId:process.env.GITHUB_RUN_ID,usage:db.usageSnapshot()});}}else out.status='D1_ADMISSION_BLOCKED';
out.d1_usage=db.usageSnapshot();await fs.mkdir('audit-output',{recursive:true});await fs.writeFile('audit-output/original-trigger-price-windows.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({status:out.status,cases:out.cases.map(c=>({contract:c.contract,history_status:c.history_status,points:c.points,retained_price_trigger_reached:c.retained_price_trigger_reached})),d1_usage:out.d1_usage,error:out.error}));if(out.status!=='EXACT_RETAINED_TTL_PRICE_WINDOWS_READ')process.exitCode=1;
